import React, { forwardRef } from 'react';
import styled from 'styled-components';

import Colors from '@dynatrace/strato-design-tokens/colors';

import type { DataTestId } from '../../core/types/data-props.js';
import type { StylingProps } from '../../core/types/styling-props.js';
import { _isStringChildren } from '../../core/utils/is-string-children.js';
import { getTextStyle } from '../../core/utils/styles/text-styles.js';
import { Text } from '../../typography/Text.js';

//#region Typings
/** Accepted properties for the TitleBar Subtitle */
export interface TitleBarSubtitleProps extends StylingProps, DataTestId {
  /** Elements to be displayed in the TitleBar Subtitle slot. */
  children: React.ReactNode;
}
//#endregion

//#region Styled Components
const StyledSubtitle = /* @__PURE__ */ styled('div')({
  ...getTextStyle('base'),
  color: Colors.Text.Neutral.Subdued,
});
//#endregion

/** TitleBar Subtitle component */
export const Subtitle = /* @__PURE__ */ forwardRef<
  HTMLDivElement,
  TitleBarSubtitleProps
>((props, forwardedRef) => {
  const {
    children,
    className: consumerClassName,
    style: consumerStyle,
    'data-testid': dataTestId,
  }: TitleBarSubtitleProps = props;
  const childIsText = _isStringChildren(props.children);

  return (
    <StyledSubtitle
      ref={forwardedRef}
      className={consumerClassName}
      style={consumerStyle}
      data-testid={dataTestId}
    >
      {childIsText ? (
        <Text textStyle="base" as="p">
          {children}
        </Text>
      ) : (
        children
      )}
    </StyledSubtitle>
  );
});
